style.css:
/* ==UserStyle==
@name Roblox Pink Lace Theme
@match *://www.roblox.com/*
==/UserStyle== */

body {
    background-image: url("https://i.imgur.com/G85njQb.jpeg") !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    background-color: #fdd9e7 !important;
}

/* soft Roblox panel tint */
div, section, main {
    background-color: rgba(255, 244, 248, 0.85) !important;
}

/* text color */
p, span, h1, h2, h3, h4, h5 {
    color: #6f5b63 !important;
}

/* links accent */
a {
    color: #2596be !important;
}
